style.css:
@-moz-document domain("roblox.com") {
:root {
        --tv-red: #dd4749;
        --tv-dark: #120b0c;
        --tv-black: #080607;
        --tv-white: #f5dddd;
    }

    /* =========================
       BACKGROUND
       ========================= */

    html,
    body {
        background: var(--tv-black) !important;
    }

    body::before {
        content: "";
        position: fixed;
        inset: 0;
        z-index: -100;
        pointer-events: none;

        background:
            linear-gradient(
                rgba(8, 6, 7, 0.38),
                rgba(8, 6, 7, 0.72)
            ),
            url("https://i.pinimg.com/originals/a6/db/f4/a6dbf4b65a1776a531ac1f9893942855.jpg?nii=t");

        background-size: cover;
        background-position: center;
        background-repeat: no-repeat;

        filter: saturate(0.9) contrast(1.05);
    }

    /* =========================
       GENERAL ROBLOX UI
       ========================= */

    .rbx-body,
    .content,
    .container-main {
        background: transparent !important;
    }

    /* Cards / panels */
    .section,
    .card,
    .table,
    .profile-header,
    .game-card,
    .games-list,
    .catalog-item {
        background: rgba(18, 11, 12, 0.82) !important;
        border-color: rgba(221, 71, 73, 0.35) !important;
        border-radius: 8px !important;
        backdrop-filter: blur(6px);
    }

    /* =========================
       TOP NAVIGATION
       ========================= */

    .nav,
    .navbar,
    .rbx-header,
    #header {
        background: rgba(8, 6, 7, 0.94) !important;
        border-bottom: 2px solid var(--tv-red) !important;
    }

    /* Roblox logo area */
    .logo,
    .icon-logo {
        filter:
            brightness(0)
            saturate(100%)
            invert(38%)
            sepia(87%)
            saturate(1300%)
            hue-rotate(325deg)
            brightness(95%);
    }

    /* Navigation links */
    .nav-link,
    .navbar-link,
    .header-link {
        color: var(--tv-white) !important;
        transition: 0.2s ease;
    }

    .nav-link:hover,
    .navbar-link:hover,
    .header-link:hover {
        color: var(--tv-red) !important;
        text-shadow: 0 0 10px rgba(221, 71, 73, 0.6);
    }

    /* =========================
       BUTTONS
       ========================= */

    .btn-primary,
    .btn-cta,
    .btn-common-play,
    button.btn-primary {
        background: var(--tv-red) !important;
        border-color: var(--tv-red) !important;
        color: white !important;
        border-radius: 5px !important;
        box-shadow: 0 0 12px rgba(221, 71, 73, 0.25);
        transition: 0.2s ease;
    }

    .btn-primary:hover,
    .btn-cta:hover,
    .btn-common-play:hover {
        background: #ef5557 !important;
        border-color: #ef5557 !important;
        box-shadow: 0 0 18px rgba(221, 71, 73, 0.55);
        transform: translateY(-1px);
    }

    /* =========================
       LINKS
       ========================= */

    a {
        color: #ef7778 !important;
    }

    a:hover {
        color: var(--tv-red) !important;
    }

    /* =========================
       TEXT
       ========================= */

    body,
    p,
    span,
    label,
    .text,
    .font-header-2 {
        color: var(--tv-white);
    }

    h1,
    h2,
    h3,
    h4,
    h5 {
        color: white !important;
        text-shadow: 0 1px 8px rgba(0, 0, 0, 0.8);
    }

    /* =========================
       SEARCH BAR
       ========================= */

    input,
    textarea,
    .input-field,
    .search-input {
        background: rgba(8, 6, 7, 0.82) !important;
        color: white !important;
        border: 1px solid rgba(221, 71, 73, 0.45) !important;
        border-radius: 5px !important;
    }

    input:focus,
    textarea:focus,
    .search-input:focus {
        border-color: var(--tv-red) !important;
        box-shadow: 0 0 0 2px rgba(221, 71, 73, 0.18) !important;
        outline: none !important;
    }

    input::placeholder,
    textarea::placeholder {
        color: #c99b9c !important;
    }

    /* =========================
       HOME PAGE GAME CARDS
       ========================= */

    .game-card:hover,
    .game-tile:hover,
    .catalog-item:hover {
        border-color: var(--tv-red) !important;
        box-shadow:
            0 0 0 1px rgba(221, 71, 73, 0.3),
            0 8px 30px rgba(0, 0, 0, 0.45);
        transform: translateY(-2px);
        transition: 0.2s ease;
    }

    /* =========================
       SIDEBAR
       ========================= */

    .left-navigation,
    .sidebar,
    .rbx-left-col {
        background: rgba(8, 6, 7, 0.82) !important;
        border-right: 1px solid rgba(221, 71, 73, 0.3) !important;
    }

    .left-navigation a:hover,
    .sidebar a:hover {
        background: rgba(221, 71, 73, 0.15) !important;
        color: var(--tv-red) !important;
    }

    /* =========================
       TABS
       ========================= */

    .tab.active,
    .tab-item.active,
    .tab.active a {
        color: var(--tv-red) !important;
        border-bottom: 2px solid var(--tv-red) !important;
    }

    /* =========================
       SCROLLBAR
       ========================= */

    ::-webkit-scrollbar {
        width: 9px;
    }

    ::-webkit-scrollbar-track {
        background: #080607;
    }

    ::-webkit-scrollbar-thumb {
        background: #552022;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: var(--tv-red);
    }

    /* =========================
       SELECTION
       ========================= */

    ::selection {
        background: var(--tv-red);
        color: white;
    }

    /* =========================
       TV GIRL VIGNETTE
       ========================= */

    body::after {
        content: "";
        position: fixed;
        inset: 0;
        z-index: 9999;
        pointer-events: none;

        background:
            radial-gradient(
                ellipse at center,
                transparent 45%,
                rgba(0, 0, 0, 0.45) 100%
            );
    }
}
